operation.add:
$data['price_raw']     = isset($product_info['price']) ? (float)$product_info['price'] : 0;
$data['product_url']   = $this->url->link('product/product', 'product_id=' . (int)$this->request->get['product_id'], true);
$data['currency_code'] = $this->config->get('config_currency');
if (!$this->document->getDescription() && !empty($product_info['description'])) {
    $this->document->setDescription(mb_substr(html_entity_decode(strip_tags($product_info['description']), ENT_QUOTES, 'UTF-8'), 0, 155));
}
if (empty($product_info['meta_title'])) {
    $auto_title = $product_info['name'];
    if (!empty($product_info['manufacturer'])) {
        $auto_title .= ' ' . $product_info['manufacturer'];
    }
    $auto_title .= ' — купить оптом | ' . $this->config->get('config_name');
    $this->document->setTitle($auto_title);
}
